#include "stdlib/stats/base/ndarray/variancetk.h"
#include "stdlib/stats/strided/dvariancetk.h"
#include "stdlib/ndarray/ctor.h"
#include "stdlib/blas/base/shared.h"
#include "stdlib/ndarray/dtypes.h"
#include <stdint.h>

/**
* Returns an ndarray element as a double-precision floating-point number.
*
* ## Notes
*
* -   If provided an unsupported data type, the function returns `NaN`.
*
* @param dtype   data type
* @param ptr     pointer to an ndarray element
* @return        element value
*/
static double get_value( const int16_t dtype, const uint8_t *ptr ) {
	switch ( dtype ) {
	case STDLIB_NDARRAY_FLOAT64:
		return *(const double *)ptr;
	case STDLIB_NDARRAY_FLOAT32:
		return (double)( *(const float *)ptr );
	case STDLIB_NDARRAY_INT32:
		return (double)( *(const int32_t *)ptr );
	case STDLIB_NDARRAY_UINT32:
		return (double)( *(const uint32_t *)ptr );
	case STDLIB_NDARRAY_INT16:
		return (double)( *(const int16_t *)ptr );
	case STDLIB_NDARRAY_UINT16:
		return (double)( *(const uint16_t *)ptr );
	case STDLIB_NDARRAY_INT8:
		return (double)( *(const int8_t *)ptr );
	case STDLIB_NDARRAY_UINT8:
	case STDLIB_NDARRAY_UINT8C:
		return (double)( *(const uint8_t *)ptr );
	default:
		return 0.0 / 0.0; // NaN
	}
}

/**
* Returns the value of a zero-dimensional ndarray as a double-precision floating-point number.
*
* @param arr   input ndarray
* @return      element value
*/
static double get_scalar( const struct ndarray *arr ) {
	const uint8_t *ptr = stdlib_ndarray_data( arr ) + stdlib_ndarray_offset( arr );
	return get_value( stdlib_ndarray_dtype( arr ), ptr );
}

/**
* Computes the variance of a one-dimensional ndarray having an arbitrary real-valued data type using a one-pass textbook algorithm.
*
* @param N            number of indexed elements
* @param correction   degrees of freedom adjustment
* @param dtype        data type
* @param ptr          pointer to the first indexed element
* @param stride       stride length (in bytes)
* @return             output value
*/
static double compute( const int64_t N, const double correction, const int16_t dtype, const uint8_t *ptr, const int64_t stride ) {
	int64_t i;
	double dN;
	double S2;
	double S;
	double n;
	double v;

	dN = (double)N;
	n = dN - correction;
	if ( N <= 0 || n <= 0.0 ) {
		return 0.0 / 0.0; // NaN
	}
	if ( N == 1 || stride == 0 ) {
		return 0.0;
	}
	S2 = 0.0;
	S = 0.0;
	for ( i = 0; i < N; i++ ) {
		v = get_value( dtype, ptr );
		S2 += v * v;
		S += v;
		ptr += stride;
	}
	return (S2 - ((S/dN)*S)) / n;
}

/**
* Computes the variance of a one-dimensional ndarray using a one-pass textbook algorithm.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a one-dimensional input ndarray.
*     -   a zero-dimensional ndarray specifying the degrees of freedom adjustment.
*
* -   The function supports the following input ndarray data types: `float64`, `float32`, `int32`, `uint32`, `int16`, `uint16`, `int8`, `uint8`, and `uint8c`. If provided an ndarray having an unsupported data type, the function returns `NaN`.
*
* @param arrays    list containing ndarrays
* @return          variance
*/
double stdlib_stats_variancetk( const struct ndarray *arrays[] ) {
	const struct ndarray *x = arrays[ 0 ];
	const double correction = get_scalar( arrays[ 1 ] );
	const int16_t dtype = stdlib_ndarray_dtype( x );
	const int64_t N = stdlib_ndarray_dimension( x, 0 );

	// For double-precision floating-point ndarrays, delegate to the optimized strided kernel:
	if ( dtype == STDLIB_NDARRAY_FLOAT64 ) {
		return API_SUFFIX(stdlib_strided_dvariancetk_ndarray)( N, correction, (const double *)stdlib_ndarray_data( x ), stdlib_ndarray_stride_elements( x, 0 ), stdlib_ndarray_offset_elements( x ) );
	}
	// Otherwise, read each element as a double-precision floating-point number:
	return compute( N, correction, dtype, stdlib_ndarray_data( x ) + stdlib_ndarray_offset( x ), stdlib_ndarray_stride( x, 0 ) );
}
